from common import ROOT,load_json,save_json,log
import pandas as pd,numpy as np,json,hashlib,zipfile
AI=[f'ST438Q0{i}DA' for i in range(1,5)];names=dict(zip(AI,['Resumir','Investigar','Redactar','Ayudar a aprender']))
def read(f):return pd.read_csv(ROOT/'results'/f)
def table(df):
    def val(x):
        if isinstance(x,(float,np.floating)):return 'NA' if pd.isna(x) else f'{x:.3g}'
        if pd.isna(x):return 'NA'
        return str(x).replace('|','/').replace('\n',' ')
    return '| '+' | '.join(df.columns)+' |\n| '+' | '.join(['---']*len(df.columns))+' |\n'+'\n'.join('| '+' | '.join(val(x) for x in row)+' |' for row in df.itertuples(index=False,name=None))
def main():
    assert load_json('results/stage2c_quality_checks.json')['status']=='PASS'
    spec=load_json('results/stage2c_specification.json');quality=load_json('results/stage2c_quality_checks.json')
    summary=read('stage2c_equal_weight_summary.csv');prog=read('model_progression_same_sample.csv');changes=read('stage2c_paired_model_changes.csv')
    ds=read('domain_specificity_tests.csv');patterns=read('stage2c_learn_pattern_tests.csv');rev=read('reverse_causality_summary.csv')
    availability=read('stage2c_variable_availability_summary.csv');national=read('stage2c_all_national_models.csv');fits=read('stage2c_fit_diagnostics.csv');support=read('school_FE_support.csv')
    comparisons=read('digital_comparison_same_sample_summary.csv');characteristics=read('heterogeneity_country_correlates.csv');reml=read('stage2c_REML_summary.csv')
    central=summary.loc[summary.domain.eq('READ')&summary.exposure.isin([AI[0],AI[2]])&summary.contrast.isin(['daily_vs_never','daily_vs_weekly'])].copy()
    def test_models(models):
        z=central.loc[central.model.isin(models)]
        passed=(z.beta.lt(0)&z.q_FDR.lt(.05)&z.K.ge(10)&z.proportion_beta_lt_0.gt(.5))
        return 'supported' if len(z) and passed.all() else ('mixed' if passed.any() else 'not supported'),int(passed.sum()),len(passed)
    h10,p10,n10=test_models(['M2-SCHOOL-FE'])
    h11,p11,n11=test_models(['M3-CONFOUNDERS','M3-INCLUDING-POTENTIAL-MEDIATORS'])
    h12,p12,n12=test_models(['JOINT-AI-USES'])
    h13data=ds.loc[ds.model.isin(['M2-CORE','M2-FULL','M2-SCHOOL-FE'])&ds.exposure.isin([AI[0],AI[2]])]
    yes13=h13data.beta.lt(0)&h13data.q_FDR_16.lt(.05);h13='supported' if yes13.all() else ('mixed' if yes13.any() else 'not supported')
    pattern_subset=patterns.loc[patterns.model.isin(['M2-CORE','M2-FULL','M2-SCHOOL-FE','M3-CONFOUNDERS','M3-INCLUDING-POTENTIAL-MEDIATORS'])]
    # Statistical pattern differences remain, but the ORIGINAL signature of
    # positive/neutral weekly and small nonrobust daily is not invariant under FE.
    all_patterns_pass=pattern_subset.q_FDR_9.lt(.05).all()
    learn=summary.loc[summary.exposure.eq(AI[3])&summary.domain.eq('READ')&summary.contrast.isin(['weekly_vs_never','daily_vs_never','daily_vs_weekly'])]
    felearn=learn.loc[learn.model.eq('M2-SCHOOL-FE')]
    changed=felearn.loc[felearn.contrast.eq('daily_vs_never'),'beta'].lt(-5).any()
    h14='mixed' if all_patterns_pass and changed else ('supported' if all_patterns_pass else 'not supported')
    h15values=[]
    for col in ['CORE_to_FULL_extra_controls_same_students_equivalence_5_points_pass','CORE_to_FULL_student_selection_equivalence_5_points_pass']:
        z=prog.loc[prog.domain.eq('READ')&prog.exposure.isin([AI[0],AI[2]])&prog.contrast.isin(['daily_vs_never','daily_vs_weekly'])]
        h15values.extend(z[col].tolist())
    z=changes.loc[changes.new_model.eq('M2-SCHOOL-FE')&changes.domain.eq('READ')&changes.exposure.isin([AI[0],AI[2]])&changes.contrast.isin(['daily_vs_never','daily_vs_weekly'])]
    h15values.extend(z.equivalence_5_points_pass.tolist());h15='supported' if all(h15values) else ('mixed' if any(h15values) else 'not supported')
    hypotheses=[
      {'hypothesis':'H10','result':h10,'evidence':f'{p10}/{n10} contrastes centrales negativos con FDR; FE conserva diario-nunca','limits':'No elimina confusión individual, selección ni causalidad inversa'},
      {'hypothesis':'H11','result':h11,'evidence':f'{p11}/{n11} contrastes negativos después de M3; acceso cambia poco, bloque actual atenúa','limits':'El bloque actual incluye variables ambiguas/mediadoras; no porcentaje causal explicado'},
      {'hypothesis':'H12','result':h12,'evidence':f'{p12}/{n12} contrastes centrales; diario-nunca de ambos usos permanece negativo; diario-semanal redactar FULL q=.067','limits':'Frecuencias correlacionadas y ajuste por otras conductas contemporáneas; asociación condicional'},
      {'hypothesis':'H13','result':h13,'evidence':f'{int(yes13.sum())}/{len(yes13)} diferencias respaldan especificidad; READ-MATH más negativo, READ-SCIE no robusto en FULL','limits':'PV emparejado como sensibilidad; inferencia principal conservadora; escalas de dominio diferentes'},
      {'hypothesis':'H14','result':h14,'evidence':'Patrones difieren en todas las pruebas Wald; FE vuelve semanal ligeramente negativo y diario-nunca ~-10 puntos','limits':'La comparación sigue distinta, pero la firma completa de 2B no permanece'},
      {'hypothesis':'H15','result':h15,'evidence':f'{sum(h15values)}/{len(h15values)} equivalencias +/-5 puntos en contrastes centrales, con IC90 emparejados','limits':'Regla de magnitud absoluta para READ resumir/redactar; no equivale a todos los usos/dominios; M3 temporal sí atenúa'}]
    h=pd.DataFrame(hypotheses);h.to_csv(ROOT/'results/stage2c_hypothesis_summary.csv',index=False,encoding='utf-8-sig')
    conclusions='La explicación específica de sustitución cognitiva **permanece indeterminada frente a selección/causalidad inversa**. Las nuevas pruebas fortalecen la robustez de las asociaciones condicionales de resumir/redactar y debilitan una explicación basada exclusivamente en diferencias entre escuelas o acceso digital. No satisfacen todos los criterios predefinidos para atribuir mayor plausibilidad específica al mecanismo: la diferencia frente a ciencias no es robusta en FULL, la comparación aprender cambia con FE y ciertos comportamientos digitales también muestran asociaciones negativas. Selección y confusión residual continúan siendo explicaciones importantes compatibles con los datos; ningún diagnóstico identifica la dirección causal.'
    lines=['# ETAPA 2C — Robustez, confusión y mecanismo',
      '\nEstado: **COMPLETE — PASS WITH RESTRICTED ESTIMAND**. Fecha: 2026-10-06, America/Bogota. La validación estadística pasó. No se ha analizado LDW ni redactado el artículo final.',
      '\n'+conclusions,
      '\n## Estimando y decisiones anteriores a los coeficientes',
      'Asociaciones nacionales ponderadas entre frecuencia autorreportada y rendimiento entre respondientes válidos a ST438 con covariables observadas, en sistemas OCDE candidatos con >=75% ponderado en los cuatro ítems y cobertura conjunta >=75% para la especificación. No representa automáticamente toda la población PISA ni todos los jóvenes de 15 años. ISR/USA permanecen fuera del conjunto principal aprobado. CORE conserva tres confusores de contexto —ESCS, IMMIG y lengua doméstica— por disponibilidad y justificación, sin escoger por signo o significancia. FULL conserva ESCS, sexo del marco ST004D01T, AGE, IMMIG y lengua doméstica. Las decisiones y criterios se registran en STAGE_2C_PLAN.md y results/stage2c_specification.json.',
      'ESCS e IMMIG están disponibles en 35/36 sistemas y lengua doméstica en 36/36; sexo supera 75% solo en 24/36, con ausencia total en 12; AGE desaparece en LUX/NOR. Añadir edad al núcleo por obligatoriedad impediría recuperar esos dos sistemas, dentro de un intervalo etario estrecho. Sexo puede ser un confusor relevante que CORE no controla: el núcleo gana comparabilidad, no sustituye la sensibilidad FULL. No se elimina migración/lengua únicamente para rescatar CRI, donde ESCS/IMMIG están ausentes.',
      table(availability.loc[availability.candidate.isin(['ESCS','IMMIG','ST022Q01TA','ST004D01T','AGE'])]),
      'CORE se estima en 35 países; su síntesis incluye **32**, porque CAN/CHL/DEU no alcanzan 75% conjunto, además de CRI no estimable. FULL mantiene **21** y reproduce los 1.260 contrastes 2B: diferencia máxima beta '+f'{quality["max_full_beta_error"]:.3g}'+', SE '+f'{quality["max_full_SE_error"]:.3g}'+'. Las filas bajo cobertura o no estimables se conservan con flags y NA.',
      '\n## Varianza y verificación',
      'Cada especificación nacional se reestima con W_FSTUWT y 80 W_FSTURWT, para los diez PV de READ/MATH/SCIE. Para vector theta: U = media_m[sum_r(delta_mr delta_mr′)/20], B = cov_m(theta_m0), T = U + 1.1 B. No se regresa sobre la media individual de PV. El mismo X admite 30 respuestas como RHS, sin mezclarlas: es álgebra equivalente a 30 ajustes separados. Media igualitaria nacional, Var(media)=sum(T_c)/K²; no se agrupan réplicas independientes de distintos países. Se conserva SENWT en el reducido; la síntesis principal usa coeficientes nacionales iguales.',
      'BH controla por separado todos los contrastes exposición/dominio/frecuencia de cada modelo/base (60 para cuatro usos IA), 16 diferencias de dominio y nueve pruebas de patrones. Todas las nuevas hipótesis son secundarias de 2C; las familias separadas no controlan un error global de todas las etapas. IC normales de 95%; equivalencia H15 usa IC90 y margen +/-5 puntos fijado antes de revisar los nuevos coeficientes. Q/I² y REML-Hartung–Knapp modificada son secundarios; la incertidumbre de la media igualitaria corresponde al conjunto fijo de países.',
      f'Verificación independiente: {quality["independent_real_school_dummy_QR_checks"]} ajustes con QR e indicadores explícitos de escuela, AUT/MEX/FRA, PV/réplicas distintos; error máximo {quality["max_QR_error"]:.3g}. Prueba sintética con pesos que cambian dentro de cada escuela: absorción correcta error {quality["synthetic_replica_absorption_check"]["max_abs_error_correct_absorption"]:.3g}; reutilizar la transformación del peso final produce un error de {quality["synthetic_replica_absorption_check"]["max_error_reusing_final_weight_transformation"]:.3f} puntos. FDR, cobertura, NA, resúmenes nacionales y descomposición se comprobaron independientemente.',
      '\n## Separar países, estudiantes y controles: A–E']
    daily=prog.loc[prog.domain.eq('READ')&prog.contrast.eq('daily_vs_never')].copy();daily['Uso']=daily.exposure.map(names)
    lines.extend([table(daily[['Uso','A_M1_36_beta','B_M1_21_beta','C_M2_CORE_all_eligible_beta','D_M2_CORE_21_beta','E_M2_FULL_21_beta']]),
      'A=M1 36 países; B=M1 exactamente los 21 FULL; C=CORE 32 elegibles; D=CORE exactamente esos 21; E=FULL 21. Estos cinco números no bastan para atribuir un cambio a controles: también cambian respondientes. Se reestimó M1 sobre los casos completos de CORE y FULL y CORE sobre los mismos casos FULL.',
      table(daily[['Uso','A_to_C_country_component','A_to_C_student_selection_component','A_to_C_controls_same_students_component','A_to_C_total']]),
      'Las tres columnas suman exactamente el cambio A→C. En resumir diario, cambiar a los 21 países por sí solo desplaza M1 de -28.83 a -27.12 (+1.71); en redactar, de -25.99 a -22.99 (+3.00). En cambio, ajustar CORE sobre los mismos estudiantes amplía la asociación negativa promedio: no toda atenuación/expansión es selección de países. results/model_progression_same_sample.csv contiene las 60 progresiones, N/K, listas, IC y cambios emparejados. Esta es una descomposición descriptiva, no una descomposición de sesgo causal.',
      '\n![Progresión](figures/model_progression.png)',
      '\n## Efectos fijos de escuela: prueba prioritaria',
      'Se usa CNT+CNTSCHID y absorción ponderada. Por cada réplica: G=X′WX−sum_s(X_s′w_s)(w_s′X_s)/sum_s(w_s) y R=X′WY−sum_s(X_s′w_s)(w_s′Y_s)/sum_s(w_s). Se recalculan sumas y denominadores escolares con cada peso; las medias de Y son distintas para cada PV. Esto equivale a Frisch–Waugh–Lovell con transformación within. No se reutiliza una única transformación del peso final.',
      'Se exige >=30 escuelas informativas, >=30 alumnos en cada categoría y rango/condición suficiente en las 81 estimaciones. Las escuelas sin variación se registran y conservan: no identifican directamente los indicadores IA, pero pueden informar controles con variación interna. Se publica por escuela la varianza ordinal ponderada, categorías y alumnos; también el número de escuelas donde cada nivel coincide con nunca. El soporte de grafo completo se confirma por rango del sistema, no requiere que todos los pares estén en cada escuela.',
      'FE CORE sintetiza 30 países; FE FULL 21. ISL/LUX tienen CNTSCHID completamente ausente en el PUF analítico y no se inventa escuela; CRI no tiene casos CORE. CAN/CHL/DEU permanecen estimados bajo 75% en el apéndice nacional. No se interpreta la muestra PISA de alumnos como una muestra representativa de todas las escuelas del país.',
      table(changes.loc[changes.new_model.eq('M2-SCHOOL-FE')&changes.domain.eq('READ')&changes.exposure.isin([AI[0],AI[2]])&changes.contrast.isin(['daily_vs_never','daily_vs_weekly']),['base_controls','exposure','contrast','K','old_beta_same_sample','new_beta','delta_beta','SE_delta','percent_attenuation_magnitude']]),
      'Para diario–nunca, FE atenúa solo 0.2%/2.3% en CORE y 1.5%/4.6% en FULL para resumir/redactar. Diario–semanal sí se atenúa 14–27%, conservando asociaciones negativas. Por tanto, las diferencias entre escuelas no explican por sí solas los dos contrastes diario–nunca. Esta persistencia no elimina diferencias individuales no observadas dentro de las escuelas ni asignación a grupos/clases, y no es un efecto causal.',
      '\n![FE](figures/school_FE_comparison.png)',
      '\n## M3: confusores plausibles y bloque temporalmente ambiguo'] )
    conceptual=read('M2_core_country_availability.csv')[['candidate','conceptual_class','reason']].drop_duplicates();conceptual=conceptual.loc[conceptual.candidate.isin(['ST250Q02JA','ST250Q05JA','ST326Q01JA','ST326Q02JA','ST326Q04JA','ST326Q05JA','ST097Q06DA'])]
    lines.extend([table(conceptual),'M3-CONFOUNDERS añade acceso a computadora e internet domésticos; son oportunidades plausiblemente anteriores al uso actual, con temporalidad no observada. M3-INCLUDING-POTENTIAL-MEDIATORS añade los cuatro tiempos digitales predefinidos y distracción en ciencias. Los tiempos actuales se clasifican ambiguos, no se declaran preexposición. Los indicadores son flexibles: nueve categorías de horas, cuatro de distracción; ninguna pendiente lineal por código ordinal.',
      table(changes.loc[changes.new_model.str.startswith('M3-')&changes.domain.eq('READ')&changes.exposure.isin([AI[0],AI[2]])&changes.contrast.isin(['daily_vs_never','daily_vs_weekly']),['new_model','base_controls','exposure','contrast','K','old_beta_same_sample','new_beta','percent_attenuation_magnitude']]),
      'Sobre mismos estudiantes/países, añadir acceso cambia menos de un punto los contrastes centrales. Añadir el bloque digital actual reduce magnitud diario–nunca aproximadamente 25–32% y diario–semanal 54–65%; los cuatro contrastes siguen negativos con FDR en CORE/FULL. No se presenta esa reducción como porcentaje de efecto causal explicado: podría retirar confusión, bloquear mediación, inducir condicionamiento o reflejar error común de autoinforme. Cobertura disminuye a K=21 CORE y K=18 FULL. Todos los coeficientes por dominio/nivel y casos bajo cobertura se conservan.',
      '\n## Cuatro usos simultáneos: asociación propia y soporte'] )
    corr=read('AI_use_correlations.csv');globalcorr=corr.loc[corr.country.eq('OECD_EQUAL_COUNTRY')]
    lines.extend([table(globalcorr[['exposure_A','exposure_B','rho','SE','K']]),
      'Correlaciones ordinales: Pearson de rangos medios ponderados por la CDF de cada categoría; rangos recalculados por réplica. Se publican por país, media igualitaria de correlaciones y correlación de una tabla descriptiva agrupada con igual peso nacional. La agrupada no tiene SE basado en réplicas internacionales conjuntas. Las 625 combinaciones y las seis tablas bivariadas se publican con ceros y N<10; el modelo aditivo no estima 625 interacciones.',
      f'En modelos conjuntos estimados, VIF máximo de indicadores IA={fits.loc[fits.model.eq("JOINT-AI-USES"),"max_AI_dummy_VIF"].max():.2f}; condición máxima del diseño estandarizado={fits.loc[fits.model.eq("JOINT-AI-USES"),"standardized_design_condition"].max():.2f}, frente a límites predefinidos 10 y 30. La colinealidad aumenta errores y puede redistribuir asociaciones, pero no hace fallar esos límites. Conjunto CORE K=30; FULL K=20, con FRA bajo 75% conjunto. ISL también queda bajo 75% conjunto CORE; no se excluyeron por signos. Las filas nacionales incluyen razones de no estimación, inflación de SE y cambios de signo frente al análisis separado en la misma muestra.',
      table(central.loc[central.model.eq('JOINT-AI-USES'),['base_controls','exposure','contrast','beta','SE','CI95_low','CI95_high','q_FDR','K','proportion_beta_lt_0']]),
      'Resumir/redactar conservan una asociación propia diario–nunca condicionada a los otros tres usos. Redactar diario–semanal FULL se reduce a -3.20 puntos, q=.067, por lo que H12 no es plenamente supported con la regla fijada para todos los contrastes centrales. Aprender pasa a asociaciones positivas grandes en el modelo conjunto (CORE diario–nunca +34.45, FULL +29.93), mientras investigar diario–nunca se vuelve +4.52 CORE y +0.63 FULL. Estos cambios muestran redistribución/supresión entre comportamientos correlacionados: no demuestran beneficios de aprender ni daños propios de sustituir.',
      '\n## Especificidad: diferencia directa READ−MATH y READ−SCIE',
      'Se usan las mismas muestras y se obtiene la covarianza completa de diferencias de coeficientes con las mismas réplicas y PV. La guía general OCDE usa valores emparejados por número para dominios conjuntamente escalados; el borrador técnico 2025 sigue inaccesible. Por eso se publica esa combinación como sensibilidad y se toma una inferencia conservadora principal: U máximo sobre emparejamientos PV posibles (asignación 10x10) + 1.1*(sqrt(B_READ)+sqrt(B_otro))². La cota conserva la covarianza muestral observada y no certifica alineación 2025 solo por los nombres. No se compara significancia aislada de dos coeficientes. La conclusión frente a ciencias en FULL no cambia entre ambas opciones.',
      table(h13data[['model','base_controls','exposure','contrast','difference','beta','SE','q_FDR_16','q_FDR_16_paired_PV']]),
      'Lectura es más negativa que matemáticas en diario–nunca para ambos usos, y generalmente en diario–semanal; en FULL redactar diario–semanal frente a MATH pierde evidencia con la cota conservadora. Frente a ciencias, FULL diario–nunca es +0.93/+0.86 puntos para resumir/redactar y no difiere claramente de cero: magnitudes similares en READ/SCIE debilitan la interpretación específicamente lingüística y siguen siendo compatibles con confusión general. CORE muestra diferencias pequeñas de ~-2 puntos frente a ciencias, dependientes de especificación/incertidumbre. Los puntos de las escalas no prueban una métrica cognitiva idéntica; CSV añade diferencias divididas por la SD nacional del dominio como sensibilidad descriptiva.',
      '\n![Dominios](figures/domain_specificity.png)',
      '\n## Diagnóstico de causalidad inversa y antecedentes',
      'Se buscaron repetición primaria/secundaria, grado y ausencias. Se usó repetición primaria como el antecedente más defendible; no existe fecha de inicio de IA que garantice el orden en cada estudiante. Repetición secundaria puede coincidir con adopción; ausentismo de las últimas dos semanas es concurrente y no se trata como confusor previo. Grado actual puede reflejar trayectoria/repetición, pero también selección educativa y no se incorpora automáticamente. No se controla PISA actual, motivación o autoeficacia.',
      table(rev.loc[rev.group.eq('daily_minus_never'),['exposure','diagnostic','K','estimate','SE','q_FDR_diagnostic']]),
      'estimate es diferencia de prevalencia en escala 0–1; multiplicar por 100 da puntos porcentuales. Usuarios diarios no muestran exceso promedio de repetición primaria: diario−nunca resumir -0.35 pp (q=.131), redactar -0.70 pp (q=.0014). Esto contradice la versión simple de que todos los usuarios diarios provienen desproporcionadamente de ese antecedente, sin descartar dificultad académica no observada ni causalidad inversa. Cada prevalencia/categoría y diferencia nacional está en reverse_causality_diagnostics.csv. La síntesis exige cobertura conjunta >=75%, con K variable por antecedente.',
      table(changes.loc[changes.new_model.eq('M2-CORE-PRIMARY-REPETITION')&changes.domain.eq('READ')&changes.exposure.isin([AI[0],AI[2]])&changes.contrast.isin(['daily_vs_never','daily_vs_weekly']),['exposure','contrast','K','old_beta_same_sample','new_beta','delta_beta','SE_delta']]),
      'Añadir repetición primaria en la misma muestra K=27 no elimina la asociación: cambia diario–nunca aproximadamente -0.32/-0.37 puntos. Es una sensibilidad de antecedente, nunca una corrección de causalidad inversa. No se usó desempeño actual como proxy de dificultad previa.',
      '\n## Comparadores digitales: no hay un negative control validado'] )
    own=comparisons.loc[comparisons.domain.eq('READ')&comparisons.exposure.eq(comparisons.digital_comparator)&comparisons.contrast.isin(['daily_vs_never','over_7h_vs_none','all_time_vs_never'])]
    lines.extend([table(own[['digital_comparator','contrast','beta','SE','CI95_low','CI95_high','K','q_FDR_comparison']]),
      'IC171Q01=computadora fuera de escuela; Q05=software educativo; Q06=juegos; IC176Q02=navegar para tareas, Q05=subir/compartir trabajo; IC177Q07=crear/editar contenido propio; ST322Q07=ansiedad sin dispositivo. Los ítems separan tareas/recursos de la pregunta explícita de IA, pero no garantizan ausencia de IA dentro de herramientas o producción. Se llaman comparison controls, no controles negativos causales. La ansiedad es contemporánea; tampoco se impone como control preexistente.',
      'Cada comparador y los cuatro usos IA se ajustan por CORE sobre exactamente los mismos estudiantes. K=11–19 por tarea; el patrón digital es heterogéneo: computadora/navegar muestran asociaciones positivas, software/dependencia y producción extremadamente intensiva muestran negativas, juegos negativas pequeñas. Crear contenido >7h/día frente a nada no es la misma intensidad que IA diario; la magnitud -81.26 no es comparable como si fueran tratamientos equivalentes. El resultado no respalda una única regla «todo uso digital intensivo es negativo», pero la negatividad tampoco es exclusiva de las preguntas IA. No se atribuye el parecido a un mecanismo común identificado. Category6 de IC171 significa recurso no disponible y se mantiene como indicador aparte; ST3226 no aplicable se excluye y documenta. Las demás frecuencias aparecen con nombres correctos.',
      '\n## La comparación ayudarme a aprender'] )
    lines.extend([table(learn.loc[learn.model.isin(['M2-CORE','M2-FULL','M2-SCHOOL-FE','M3-CONFOUNDERS','M3-INCLUDING-POTENTIAL-MEDIATORS','JOINT-AI-USES']),['model','base_controls','contrast','beta','SE','q_FDR','K']]),
      'Los vectores siguen significativamente diferentes de resumir/redactar/investigar en todas las pruebas Wald por dominio/modelo (BH9). Sin embargo, la firma de 2B no es invariante: FULL semanal +6.10 pasa a FE FULL -1.97; diario−nunca -2.75 pasa a -10.62; diario−semanal permanece -8.65. El bloque digital actual vuelve semanal próximo a cero; el modelo conjunto cambia diario−semanal de signo. Se conserva el argumento de que la forma de uso se asocia de manera diferente, y se evita presentarlo como mecanismo establecido o reproducir automáticamente la firma original.',
      '\n## Heterogeneidad, REML y características nacionales'] )
    htable=central.loc[central.model.isin(['M2-CORE','M2-FULL','M2-SCHOOL-FE','M3-CONFOUNDERS','M3-INCLUDING-POTENTIAL-MEDIATORS','JOINT-AI-USES'])]
